        public void Continue()
        {
            if (!MachineHardwareConfiguration.GetInstance().IsSafeDoorConfigured)
            {
                Machine.GetInstance().SetState(MachineStateEnum.Working);
            }
            else
            {
                if (!this.IsSafeDoorClose)
                {
                    AKRSXtraMessageBox.Show("请先关好安全门");
                }
                else
