            if (!this.AllAxisReset)
            {
                AKRSXtraMessageBox.Show("启动前请先总复位");
                return false;
            }

            this.ReadyToLog();

            if (!this.IsAllowTaskClosed())
            {
                AKRSXtraMessageBox.Show($"部分模组仍在工作,不能启动，请关闭后重试");
                return false;
